style.css:
@-moz-document domain("discord.com") {
.theme-dark, .theme-light {
    /* Main Background Colors */
    --background-primary: #08080a !important;      /* Main chat & friends area */
    --background-secondary: #111116 !important;    /* Sidebar (DMs) & Right panel */
    --background-secondary-alt: #15151b !important;/* Inner cards and secondary elements */
    --background-tertiary: #08080a !important;     /* Server list (far left) */
    --background-floating: #111116 !important;     /* Context menus and popups */
    
    /* Message box and search bars */
    --channeltextarea-background: #15151b !important;
    
    /* Hover and Selection states */
    --background-modifier-hover: rgba(255, 255, 255, 0.04) !important;
    --background-modifier-active: rgba(255, 255, 255, 0.06) !important;
    --background-modifier-selected: rgba(255, 255, 255, 0.08) !important;
    
    /* Darkened Scrollbars */
    --scrollbar-auto-thumb: #22222a !important;
    --scrollbar-auto-track: transparent !important;
    --scrollbar-thin-thumb: #22222a !important;
    --scrollbar-thin-track: transparent !important;
  }

  /* --- Bottom Left User Profile Area --- */
  section[class^="panels_"] {
    /* You can replace the URL below with a direct link to any image you want */
    background-image: url("https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=500&auto=format&fit=crop") !important; 
    background-size: cover !important;
    background-position: center !important;
    border-top: 1px solid rgba(255, 255, 255, 0.03) !important;
  }

  /* Makes the user area slightly transparent so the image shows through nicely */
  section[class^="panels_"] > div {
    background-color: rgba(17, 17, 22, 0.65) !important;
    backdrop-filter: blur(2px);
  }
}
